import { useState } from 'react';
import { Button, Group, Stack, TextInput } from '@mantine/core';
import { formRootRule, isNotEmpty, useForm } from '@mantine/form';
import { randomId } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';
import { TasksList } from './TasksList';
import { TasksValues } from './types';

export function ReorderListItems() {
  const [draft, setDraft] = useState('');

  const form = useForm<TasksValues>({
    initialValues: {
      items: [
        {
          key: randomId(),
          title: 'Write release notes',
        },
        {
          key: randomId(),
          title: 'Review pull requests',
        },
        {
          key: randomId(),
          title: 'Update dependencies',
        },
        {
          key: randomId(),
          title: 'Publish the release',
        },
      ],
    },
    validate: {
      items: {
        [formRootRule]: isNotEmpty('Add at least one task'),
        title: isNotEmpty('Task title is required'),
      },
    },
  });

  const addItem = () => {
    const title = draft.trim();
    if (title.length > 0) {
      form.insertListItem('items', {
        key: randomId(),
        title,
      });
      setDraft('');
    }
  };

  const handleSubmit = (values: TasksValues) => {
    notifications.show({
      title: 'Tasks saved',
      message: `${values.items.length} ${values.items.length === 1 ? 'task' : 'tasks'} saved`,
    });
  };

  return (
    <form onSubmit={form.onSubmit(handleSubmit)}>
      <Stack>
        <Group gap="xs" wrap="nowrap" align="flex-end">
          <TextInput
            size="md"
            label="New task"
            placeholder="Buy milk"
            style={{ flex: 1 }}
            value={draft}
            onChange={(event) => setDraft(event.currentTarget.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                addItem();
              }
            }}
          />

          <Button size="md" variant="default" onClick={addItem}>
            Add
          </Button>
        </Group>

        <TasksList form={form} />

        <Group justify="flex-end">
          <Button size="md" type="submit">
            Save order
          </Button>
        </Group>
      </Stack>
    </form>
  );
}

import { useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { DotsSixVerticalIcon, TrashIcon } from '@phosphor-icons/react';
import { ActionIcon, Group, TextInput } from '@mantine/core';
import { TasksForm } from './types';

interface SortableItemProps {
  id: string;
  index: number;
  form: TasksForm;
}

export function SortableItem({ id, index, form }: SortableItemProps) {
  const { attributes, listeners, setNodeRef, transform, transition } = useSortable({ id });

  return (
    <Group
      ref={setNodeRef}
      gap="xs"
      wrap="nowrap"
      align="flex-start"
      style={{ transform: CSS.Transform.toString(transform), transition }}
    >
      <ActionIcon
        variant="default"
        size="input-md"
        aria-label="Drag to reorder"
        style={{ cursor: 'grab', touchAction: 'none' }}
        {...attributes}
        {...listeners}
      >
        <DotsSixVerticalIcon size={18} />
      </ActionIcon>

      <TextInput
        size="md"
        placeholder="What needs to be done?"
        aria-label="Task"
        style={{ flex: 1 }}
        {...form.getInputProps(`items.${index}.title`)}
      />

      <ActionIcon
        variant="default"
        size="input-md"
        aria-label="Remove task"
        onClick={() => form.removeListItem('items', index)}
      >
        <TrashIcon size={18} color="var(--mantine-color-red-6)" />
      </ActionIcon>
    </Group>
  );
}

import {
  closestCenter,
  DndContext,
  DragEndEvent,
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
} from '@dnd-kit/core';
import {
  SortableContext,
  sortableKeyboardCoordinates,
  verticalListSortingStrategy,
} from '@dnd-kit/sortable';
import { Input, Stack, Text } from '@mantine/core';
import { SortableItem } from './SortableItem';
import { TasksForm } from './types';

interface TasksListProps {
  form: TasksForm;
}

export function TasksList({ form }: TasksListProps) {
  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates })
  );

  const ids = form.useWatchValue('items').map((item) => item.key);

  const handleDragEnd = ({ active, over }: DragEndEvent) => {
    if (over && active.id !== over.id) {
      form.reorderListItem('items', {
        from: ids.indexOf(String(active.id)),
        to: ids.indexOf(String(over.id)),
      });
    }
  };

  return (
    <div>
      <DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={handleDragEnd}>
        <SortableContext items={ids} strategy={verticalListSortingStrategy}>
          <Stack gap="xs">
            {ids.map((id, index) => (
              <SortableItem key={id} id={id} index={index} form={form} />
            ))}
          </Stack>
        </SortableContext>
      </DndContext>

      {ids.length === 0 && (
        <Text size="sm" ta="center">
          No tasks yet
        </Text>
      )}

      {form.errors.items && (
        <Input.Error size="md" mt="xs">
          {form.errors.items}
        </Input.Error>
      )}
    </div>
  );
}

import { UseFormReturnType } from '@mantine/form';

export interface TaskItem {
  key: string;
  title: string;
}

export interface TasksValues {
  items: TaskItem[];
}

export type TasksForm = UseFormReturnType<TasksValues>;
